// genproto's grafeas/v1 and containeranalysis/v1 packages are generated by
// the old plugin: their Register functions take a *grpc.Server and their
// service descriptors are unexported, so the JSON transcoder, a
// grpc.ServiceRegistrar, cannot be given them. These descriptors are the
// same services, method by method.

func unary[Req any, Resp any](service, method string, call func(srv any, ctx context.Context, r *Req) (Resp, error)) grpc.MethodDesc {
	full := "/" + service + "/" + method
	return grpc.MethodDesc{MethodName: method, Handler: func(srv any, ctx context.Context, dec func(any) error, ic grpc.UnaryServerInterceptor) (any, error) {
		in := new(Req)
		if err := dec(in); err != nil {
			return nil, err
		}
		if ic == nil {
			return call(srv, ctx, in)
		}
		return ic(ctx, in, &grpc.UnaryServerInfo{Server: srv, FullMethod: full}, func(ctx context.Context, r any) (any, error) {
			return call(srv, ctx, r.(*Req))
		})
	}}
}

